import{_ as s,l as o,o as e,c as n,v as t,p as l,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"等价关系与划分","description":"","frontmatter":{"title":"等价关系与划分","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/equivalence-partition.md","filePath":"cs/equivalence-partition.md","lastUpdated":1789023840000}'),h={name:"cs/equivalence-partition.md"};function E(m,a,A,_,u,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="等价关系与划分" tabindex="-1">等价关系与划分 <a class="header-anchor" href="#等价关系与划分" aria-label="Permalink to &quot;等价关系与划分&quot;">​</a></h1><div class="epigraph"><p>自反、对称、传递的关系，正好把集合切成互不重叠的块；块里的元素彼此可替换，块与块之间不可。</p><footer>—— 据 Rosen, Discrete Mathematics and Its Applications 整理</footer></div><p>上一课<a href="/cs/sets-relations">集合与关系</a>钉死了关系是有序对的集合，并点名「等价 \\(\\Leftrightarrow\\) 划分」，当时不证、不展开类。本课不重讲笛卡尔积，也不从「抽象代数」另起。缺口是：后课同余、连通分量、类型等价，都要把「当成同一个」写成类。点名不够，必须把对应钉成双向构造。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>关系可以只对称不传递（「相邻」），或只传递不对称。缺口因此不是新的 \\(\\subseteq\\)，而是三条一起：<strong>等价关系</strong> \\(\\sim\\)。对 \\(a\\in A\\)，类 \\([a]=\\{x:x\\sim a\\}\\)。全体类构成 \\(A\\) 的划分：非空、互不相交、并集为 \\(A\\)。反过来，给定划分，定义「在同一块里」即得等价关系。两构造互逆。</p><p>模 \\(n\\) 同余是本栏已经用过的例子：位权课的模 \\(2^n\\) 加法，现在有了关系语言。连通分量要等<a href="/cs/graph-definition">图</a>有了边再写；本课只准备「类」。</p><h3 id="类不是「随便分组」" tabindex="-1">类不是「随便分组」 <a class="header-anchor" href="#类不是「随便分组」" aria-label="Permalink to &quot;类不是「随便分组」&quot;">​</a></h3><p>每一对相关的元素必须进同一块，无关的不能进同一块。把学生「随便分成若干组」当成等价类，后课商集没有运算。也不把偏序的可比当成对称：下一课序关系故意丢掉对称、改用反对称。</p><p><span class="marginnote">Rosen 用同余与「相同余数」当主例，并证明等价与划分一一对应。商集 \\(A/{\\sim}\\) 是类的集合；后课函数要对类良定义，须与代表元无关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证 \\(\\sim\\) 三性质；写出几个类，检查相交为空。从划分回到关系：\\((a,b)\\in R\\) 当且仅当存在一块同时含 \\(a,b\\)。细化：更细的划分对应更小的等价关系（作为有序对集合）。本课不引入格——那是<a href="/cs/poset-lattice">下一课</a>用包含关系做的。</p>',11)),(e(),l(c,null,{default:i(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22%E5%85%B3%E7%B3%BB%22%5D%20--%3E%20EQ%5B%22%E8%87%AA%E5%8F%8D%E5%AF%B9%E7%A7%B0%E4%BC%A0%E9%80%92%22%5D%0A%20%20EQ%20--%3E%20CLS%5B%22%E7%AD%89%E4%BB%B7%E7%B1%BB%22%5D%0A%20%20CLS%20--%3E%20PART%5B%22%E5%88%92%E5%88%86%22%5D%0A%20%20PART%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%81%8F%E5%BA%8F%E4%B8%A2%E6%8E%89%E5%AF%B9%E7%A7%B0%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了类，才能说「模 \\(2^n\\) 下相等」是关系，而不是散文。后课哈希碰撞是「不同键映到同一槽」，那是函数不是等价——除非再定义核。布尔函数相等是真值表相同，是函数集合上的等价；化简课已经在用，现在有名字。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论选择公理下的怪划分，不把群的正规子群提前。偏序、格、函数单射满射都还没钉。有限与无限只影响类的个数是否可数，可数是再后一课。</p><p>后课默认：谈到「同一类 / 同余 / 商」，先给出等价关系或划分二者之一，另一份跟着来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>等价关系的类构成划分；划分诱导等价关系。</li><li>同余是已用过的模算术的关系写法。</li><li>下一课改谈反对称的序，不再对称。</li><li>出处：Rosen, <em>Discrete Mathematics and Its Applications</em>。</li></ul>',7))])}const b=s(h,[["render",E]]);export{q as __pageData,b as default};
